import time
from pathlib import Path

from langchain_core.tools import tool

LOG_ROOT = Path("/var/log/apps")


@tool
def purge_expired_log_files(service_name: str, max_age_days: int, pattern: str = "*.log*") -> dict:
    log_dir = (LOG_ROOT / service_name).resolve()
    if LOG_ROOT.resolve() not in log_dir.parents:
        return {"status": "error", "error": "Service path escapes the log root."}
    if not log_dir.is_dir():
        return {"status": "error", "error": f"No log directory for service '{service_name}'."}
    if max_age_days < 1:
        return {"status": "error", "error": "max_age_days must be at least 1."}

    cutoff = time.time() - max_age_days * 86400
    deleted = []
    bytes_freed = 0
    failures = []
    for path in sorted(log_dir.glob(pattern)):
        if not path.is_file():
            continue
        stat = path.stat()
        if stat.st_mtime >= cutoff:
            continue
        try:
            path.unlink()
            deleted.append(path.name)
            bytes_freed += stat.st_size
        except OSError as exc:
            failures.append({"file": path.name, "error": str(exc)})

    return {
        "status": "ok",
        "service": service_name,
        "deleted": deleted,
        "deleted_count": len(deleted),
        "bytes_freed": bytes_freed,
        "failures": failures,
    }

import os

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("log-platform")
API_BASE = os.environ.get("LOG_PLATFORM_URL", "https://logs.internal.example.com/api/v1")
HEADERS = {"Authorization": f"Bearer {os.environ.get('LOG_PLATFORM_TOKEN', '')}"}


@mcp.tool()
def grant_log_stream_access(stream_id: str, principal: str, role: str) -> dict:
    if role not in ("viewer", "editor"):
        return {"ok": False, "error": "role must be 'viewer' or 'editor'"}
    url = f"{API_BASE}/streams/{stream_id}/acl"
    resp = requests.post(url, json={"principal": principal, "role": role}, headers=HEADERS, timeout=15)
    if resp.status_code >= 400:
        return {"ok": False, "error": resp.text, "status_code": resp.status_code}
    grants = requests.get(url, headers=HEADERS, timeout=15).json().get("grants", [])
    return {"ok": True, "stream_id": stream_id, "granted": {"principal": principal, "role": role}, "grants": grants}

import re
from dataclasses import dataclass, field
from pathlib import Path

from agents import function_tool

_PATTERNS = {
    "email": (re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+"), "[REDACTED_EMAIL]"),
    "ipv4": (re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b"), "[REDACTED_IP]"),
    "token": (re.compile(r"(?i)bearer\s+[A-Za-z0-9._~+/=-]+"), "Bearer [REDACTED_TOKEN]"),
}


@dataclass
class RedactionResult:
    path: str
    lines_scanned: int = 0
    counts: dict = field(default_factory=dict)
    changed: bool = False


@function_tool
def redact_pii_in_log_file(log_path: str, redact_ips: bool = True) -> RedactionResult:
    path = Path(log_path)
    text = path.read_text(encoding="utf-8", errors="replace")
    result = RedactionResult(path=str(path), lines_scanned=text.count("\n") + 1)

    redacted = text
    for kind, (regex, marker) in _PATTERNS.items():
        if kind == "ipv4" and not redact_ips:
            continue
        redacted, n = regex.subn(marker, redacted)
        result.counts[kind] = n

    if redacted != text:
        path.write_text(redacted, encoding="utf-8")
        result.changed = True
    return result

import re
import subprocess

from agents import function_tool

_SIZE_RE = re.compile(r"^\d+[KMGT]?$")
_AGE_RE = re.compile(r"^\d+(s|min|h|d|weeks|months|years)$")


@function_tool
def vacuum_journal_logs(max_size: str = "", max_age: str = "") -> dict:
    if not max_size and not max_age:
        return {"ok": False, "error": "Provide max_size or max_age."}
    cmd = ["journalctl"]
    if max_size:
        if not _SIZE_RE.match(max_size):
            return {"ok": False, "error": f"Invalid size '{max_size}'."}
        cmd.append(f"--vacuum-size={max_size}")
    if max_age:
        if not _AGE_RE.match(max_age):
            return {"ok": False, "error": f"Invalid age '{max_age}'."}
        cmd.append(f"--vacuum-time={max_age}")

    with subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True) as proc:
        try:
            output, _ = proc.communicate(timeout=300)
        except subprocess.TimeoutExpired:
            proc.kill()
            output, _ = proc.communicate()
            return {"ok": False, "error": "journalctl vacuum timed out.", "output": output}
        returncode = proc.returncode

    freed = re.search(r"freed ([\d.]+[KMGTB]?)", output or "")
    return {
        "ok": returncode == 0,
        "command": " ".join(cmd),
        "returncode": returncode,
        "freed": freed.group(1) if freed else None,
        "output": (output or "").strip()[-4000:],
    }
